/**
 * Scene -> chain of bed clips. Generated by bake.mjs from plan.mjs: every beat is its own baked 3s cut
 * used exactly once, held for at most 90 frames. See plan.mjs for the source of each beat.
 */

export type Bed = {
  src: string;
  startFrom: number;
  span: number;
  zoom?: number;
  offX?: number;
  offY?: number;
  driftX?: number;
  driftY?: number;
  exposure?: number;
  saturate?: number;
};

export type Link = Bed & {frames: number};

const P = (name: string) => `bed-pool/${name}.mp4`;

const L = (file: string, frames: number, extra: Partial<Omit<Bed, 'src' | 'span'>> = {}): Link => ({
  src: P(file),
  startFrom: 0,
  frames,
  span: frames / 30,
  ...extra,
});

